import { test, expect } from '@playwright/test';

test.describe('Accessibility Tests for Images', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('check that all images have descriptive alt text', async ({ page }) => {
    const images = await page.locator('img').all();
    for (const image of images) {
      const altText = await image.getAttribute('alt');
      expect(altText).not.toBeNull();
      expect(altText).not.toBe('');
    }
  });

  test('check that images with specific roles have descriptive alt text', async ({ page }) => {
    const decorativeImages = await page.getByRole('img', { name: '' }).all();
    for (const image of decorativeImages) {
      const altText = await image.getAttribute('alt');
      expect(altText).toBe('');
    }

    const informativeImages = await page.getByRole('img', { name: /.+/ }).all();
    for (const image of informativeImages) {
      const altText = await image.getAttribute('alt');
      expect(altText).not.toBeNull();
      expect(altText).not.toBe('');
    }
  });
});
